"""Private Fargate queue with an infrastructure ceiling of two vCPUs."""
import json

def template(vpc,subnet,worker_sg,app_sg,app_role,bucket,kms,source):
    ref=lambda x:{'Ref':x};att=lambda x,y:{'Fn::GetAtt':[x,y]}
    tags=[{'Key':'Project','Value':'OpenNGS'}];R={}
    def add(n,t,p,**kw):R[n]={'Type':t,'Properties':p,**kw}
    add('Images','AWS::ECR::Repository',{'RepositoryName':'openngs-demo','ImageTagMutability':'IMMUTABLE','ImageScanningConfiguration':{'ScanOnPush':True},'EncryptionConfiguration':{'EncryptionType':'AES256'},'Tags':tags,'LifecyclePolicy':{'LifecyclePolicyText':json.dumps({'rules':[{'rulePriority':1,'description':'Remove untagged layers after seven days','selection':{'tagStatus':'untagged','countType':'sinceImagePushed','countUnit':'days','countNumber':7},'action':{'type':'expire'}}]})}},DeletionPolicy='Retain',UpdateReplacePolicy='Retain')
    for name in ['BuildLogs','JobLogs']:add(name,'AWS::Logs::LogGroup',{'LogGroupName':'/openngs/'+('build' if name=='BuildLogs' else 'jobs'),'RetentionInDays':7,'Tags':tags})
    add('EndpointSecurity','AWS::EC2::SecurityGroup',{'VpcId':vpc,'GroupDescription':'ECR and logs from isolated OpenNGS workers only','SecurityGroupIngress':[{'IpProtocol':'tcp','FromPort':443,'ToPort':443,'SourceSecurityGroupId':worker_sg},{'IpProtocol':'tcp','FromPort':443,'ToPort':443,'SourceSecurityGroupId':app_sg}],'SecurityGroupEgress':[{'IpProtocol':'tcp','FromPort':9,'ToPort':9,'CidrIp':'127.0.0.1/32'}],'Tags':tags})
    for name,service in [('ECRApi','ecr.api'),('ECRDocker','ecr.dkr'),('LogsEndpoint','logs')]:add(name,'AWS::EC2::VPCEndpoint',{'VpcId':vpc,'SubnetIds':[subnet],'SecurityGroupIds':[ref('EndpointSecurity')],'ServiceName':'com.amazonaws.us-east-1.'+service,'VpcEndpointType':'Interface','PrivateDnsEnabled':True})
    assume=lambda service:{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':service},'Action':'sts:AssumeRole'}]}
    log_statement={'Effect':'Allow','Action':['logs:CreateLogStream','logs:PutLogEvents'],'Resource':[att('BuildLogs','Arn'),att('JobLogs','Arn')]}
    ecr_read={'Effect':'Allow','Action':['ecr:BatchGetImage','ecr:GetDownloadUrlForLayer','ecr:BatchCheckLayerAvailability'],'Resource':att('Images','Arn')}
    token={'Effect':'Allow','Action':['ecr:GetAuthorizationToken'],'Resource':'*'}
    add('ExecutionRole','AWS::IAM::Role',{'AssumeRolePolicyDocument':assume('ecs-tasks.amazonaws.com'),'Policies':[{'PolicyName':'PullApprovedImageAndLog','PolicyDocument':{'Version':'2012-10-17','Statement':[token,ecr_read,log_statement]}}],'Tags':tags})
    statements=[token,ecr_read,log_statement,{'Effect':'Allow','Action':['ecr:InitiateLayerUpload','ecr:UploadLayerPart','ecr:CompleteLayerUpload','ecr:PutImage'],'Resource':att('Images','Arn')},{'Effect':'Allow','Action':['s3:GetObject','s3:GetObjectVersion'],'Resource':'arn:aws:s3:::'+bucket+'/'+source},{'Effect':'Allow','Action':['s3:GetBucketLocation'],'Resource':'arn:aws:s3:::'+bucket},{'Effect':'Allow','Action':['kms:Decrypt'],'Resource':kms}]
    add('BuildRole','AWS::IAM::Role',{'AssumeRolePolicyDocument':assume('codebuild.amazonaws.com'),'Policies':[{'PolicyName':'BuildOnlyOpenNGSImage','PolicyDocument':{'Version':'2012-10-17','Statement':statements}}],'Tags':tags})
    buildspec={'version':'0.2','phases':{'pre_build':{'commands':['aws ecr get-login-password --region us-east-1 | docker login --username AWS --password-stdin "$REPOSITORY"','docker pull public.ecr.aws/docker/library/python:3.13-slim-bookworm','BASE=$(docker image inspect public.ecr.aws/docker/library/python:3.13-slim-bookworm --format "{{index .RepoDigests 0}}")','echo "Pinned upstream base: $BASE"']},'build':{'commands':['docker build --build-arg "PYTHON_IMAGE=$BASE" -f infra/demo.Dockerfile -t "$REPOSITORY:$IMAGE_TAG" .']},'post_build':{'commands':['docker push "$REPOSITORY:$IMAGE_TAG"','docker image inspect "$REPOSITORY:$IMAGE_TAG" --format "{{json .RepoDigests}}"']}}}
    add('Build','AWS::CodeBuild::Project',{'Name':'openngs-demo-build','ServiceRole':att('BuildRole','Arn'),'Artifacts':{'Type':'NO_ARTIFACTS'},'Source':{'Type':'S3','Location':bucket+'/'+source,'BuildSpec':json.dumps(buildspec)},'Environment':{'Type':'LINUX_CONTAINER','ComputeType':'BUILD_GENERAL1_SMALL','Image':'aws/codebuild/standard:7.0','PrivilegedMode':True,'EnvironmentVariables':[{'Name':'REPOSITORY','Value':att('Images','RepositoryUri')},{'Name':'IMAGE_TAG','Value':ref('ImageTag')}]},'TimeoutInMinutes':20,'QueuedTimeoutInMinutes':10,'LogsConfig':{'CloudWatchLogs':{'Status':'ENABLED','GroupName':ref('BuildLogs')}},'Tags':tags})
    add('Compute','AWS::Batch::ComputeEnvironment',{'ComputeEnvironmentName':'openngs-demo-fargate','Type':'MANAGED','State':'ENABLED','ComputeResources':{'Type':'FARGATE','MaxvCpus':2,'Subnets':[subnet],'SecurityGroupIds':[worker_sg]},'Tags':{'Project':'OpenNGS'}})
    add('Queue','AWS::Batch::JobQueue',{'JobQueueName':'openngs-demo','State':'ENABLED','Priority':1,'ComputeEnvironmentOrder':[{'Order':1,'ComputeEnvironment':ref('Compute')}],'Tags':{'Project':'OpenNGS'}})
    props={'Type':'container','JobDefinitionName':'openngs-demo','PlatformCapabilities':['FARGATE'],'ContainerProperties':{'Image':ref('WorkerImage'),'Command':['MANIFEST_URL_REQUIRED'],'ResourceRequirements':[{'Type':'VCPU','Value':'2'},{'Type':'MEMORY','Value':'4096'}],'ExecutionRoleArn':att('ExecutionRole','Arn'),'User':'65534:65534','ReadonlyRootFilesystem':True,'NetworkConfiguration':{'AssignPublicIp':'DISABLED'},'FargatePlatformConfiguration':{'PlatformVersion':'LATEST'},'Volumes':[{'Name':'work'},{'Name':'tmp'}],'MountPoints':[{'SourceVolume':'work','ContainerPath':'/work','ReadOnly':False},{'SourceVolume':'tmp','ContainerPath':'/tmp','ReadOnly':False}],'LogConfiguration':{'LogDriver':'awslogs','Options':{'awslogs-group':ref('JobLogs'),'awslogs-region':'us-east-1','awslogs-stream-prefix':'demo'}}},'RetryStrategy':{'Attempts':1},'Timeout':{'AttemptDurationSeconds':3600},'Tags':{'Project':'OpenNGS','OpenNGSIsolation':'Fargate-no-task-role-curated-data-v1'}}
    add('Definition','AWS::Batch::JobDefinition',props,Condition='HasImage')
    add('AppQueuePolicy','AWS::IAM::Policy',{'PolicyName':'OpenNGSDemoQueue','Roles':[app_role],'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':['batch:SubmitJob'],'Resource':[ref('Queue'),{'Fn::Sub':'arn:aws:batch:${AWS::Region}:${AWS::AccountId}:job-definition/openngs-demo:*'}]},{'Effect':'Allow','Action':['batch:DescribeJobs','batch:DescribeJobDefinitions','batch:ListJobs'],'Resource':'*'},{'Effect':'Allow','Action':['batch:TerminateJob'],'Resource':{'Fn::Sub':'arn:aws:batch:${AWS::Region}:${AWS::AccountId}:job/*'},'Condition':{'StringEquals':{'aws:ResourceTag/Project':'OpenNGS'}}},{'Effect':'Allow','Action':['logs:GetLogEvents'],'Resource':att('JobLogs','Arn')}]}})
    return {'AWSTemplateFormatVersion':'2010-09-09','Description':'OpenNGS curated demo compute: private Fargate, 2-vCPU ceiling, no task role, no automatic fallback','Parameters':{'WorkerImage':{'Type':'String','Default':''},'ImageTag':{'Type':'String'}},'Conditions':{'HasImage':{'Fn::Not':[{'Fn::Equals':[ref('WorkerImage'),'']}]}},'Resources':R,'Outputs':{'Repository':{'Value':att('Images','RepositoryUri')},'Queue':{'Value':ref('Queue')},'JobDefinition':{'Value':{'Fn::If':['HasImage',ref('Definition'),'NotPublished']}}}}

if __name__=='__main__':
    import sys
    print(json.dumps(template(*sys.argv[1:]),indent=2))
